// Command gidtaggen writes t0-cx-core-gidtag/gidtag_gen.go from gidtag.Table:
// a constant per tag and NameTable, so a tag value prints its name. See
// docs/GidVariants.md.
//
//	go run ./t1-cx-core-gidtaggen          write the file
//	go run ./t1-cx-core-gidtaggen -check   fail if the file is stale
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"

	gidtag "github.com/skycoin/skycoin-cx/t0-cx-core-gidtag"
)

// gidtaggenFile is the generated file, relative to the repository root.
const gidtaggenFile = "t0-cx-core-gidtag/gidtag_gen.go"

// gidtaggenSource returns the generated file of table.
func gidtaggenSource(table []gidtag.Tag) ([]byte, error) {
	tags := append([]gidtag.Tag{}, table...)
	sort.Slice(tags, func(i, j int) bool { return tags[i].TagValue < tags[j].TagValue })
	var buf bytes.Buffer
	buf.WriteString("// Code generated by t1-cx-core-gidtaggen. DO NOT EDIT.\n\npackage gidtag\n\n")
	buf.WriteString("// The tags of Table, untyped so they convert to objmodel.TypeTag and uint8.\nconst (\n")
	for _, tag := range tags {
		fmt.Fprintf(&buf, "\t%s = 0x%02X\n", tag.TagName, tag.TagValue)
	}
	buf.WriteString(")\n\n// NameTable names each tag of Table. An unused tag has an empty name.\nvar NameTable = [256]string{\n")
	for _, tag := range tags {
		fmt.Fprintf(&buf, "\t0x%02X: %q,\n", tag.TagValue, tag.TagName)
	}
	buf.WriteString("}\n")
	return format.Source(buf.Bytes())
}

func main() {
	root := flag.String("root", ".", "the repository root")
	check := flag.Bool("check", false, "fail when the generated file is out of date")
	flag.Parse()
	source, err := gidtaggenSource(gidtag.Table)
	if err != nil {
		fmt.Fprintln(os.Stderr, "gidtaggen:", err)
		os.Exit(1)
	}
	path := filepath.Join(*root, gidtaggenFile)
	if *check {
		have, err := os.ReadFile(path)
		if err != nil || !bytes.Equal(bytes.ReplaceAll(have, []byte("\r\n"), []byte("\n")), source) {
			fmt.Println(gidtaggenFile, "is stale, run make generate-gidtags")
			os.Exit(1)
		}
		fmt.Println(gidtaggenFile, "up to date")
		return
	}
	if err := os.WriteFile(path, source, 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "gidtaggen:", err)
		os.Exit(1)
	}
}
